	public void Init(Player p, bool hornMode)
	{
		this.hornMode = hornMode;
		List<SanctuaryDestination> list = new List<SanctuaryDestination>();
		Player mainPlayer = PlayerMgr.GetMainPlayer();
		for (int i = 0; i < MapMgr.sanctuaryMgr.sanctuaries.Length; i++)
		{
			Sanctuary sanctuary = MapMgr.sanctuaryMgr.sanctuaries[i];
			if ((sanctuary != null && sanctuary.shrine) || mainPlayer.sanctuaryVisitCount[i] <= 0 || sanctuary.creed <= 0 || mainPlayer.creedStanding[sanctuary.creed] < 0)
			{
				continue;
			}
			if (hornMode)
			{
				for (int j = 0; j < 4; j++)
				{
					if (mainPlayer.sanctuaryPilgrim[i, j] == 6)
					{
						list.Add(new SanctuaryDestination(sanctuary, i));
						break;
					}
				}
			}
			else
			{
				list.Add(new SanctuaryDestination(sanctuary, i));
			}
		}
		dest = list.ToArray();
	}

	public override void SelectedUpdate(Player p)
	{
		if (selItem >= dest.Length)
		{
			selItem = 0;
		}
		Character playerCharacter = CharMgr.GetPlayerCharacter(p);
		if (playerCharacter == null)
		{
			return;
		}
		if (p.keyUp)
		{
			Sound.PlaySelect();
			selItem--;
			if (selItem < 0)
			{
				selItem = 0;
			}
		}
		if (p.keyDown)
		{
			Sound.PlaySelect();
			selItem++;
			if (selItem >= dest.Length)
			{
				selItem = dest.Length - 1;
				if (selItem < 0)
				{
					selItem = 0;
				}
			}
		}
		if (p.keyBCancel)
		{
			Sound.PlayCancel();
			if (hornMode)
			{
				p.dialog.menuMgr.DoSpecialTrans(0);
			}
			else
			{
				p.dialog.menuMgr.DoSpecialTrans(100);
			}
		}
		if (p.keyAccept && selItem < dest.Length)
		{
			p.fastTravelDest = MapMgr.sanctuaryMgr.sanctuaries[dest[selItem].sanctIdx].loc;
			p.fastTravelFrame = 5f;
			p.isFastTravel = true;
			ParticleManager.AddBackNormalParticle(170, playerCharacter.loc, default, 0f, 0f, -1, -1);
			if (p.dialog.npcIdx > -1)
			{
				CharMgr.character[p.dialog.npcIdx].anim.SetAnimation("chant");
			}
			if (GameStateManager.coopPlayerIdx > -1)
			{
				Player player = ((GameStateManager.coopPlayerIdx == p.ID) ? PlayerMgr.GetMainPlayer() : PlayerMgr.GetCoopPlayer());
				player.fastTravelDest = p.fastTravelDest;
				player.fastTravelFrame = p.fastTravelFrame;
				CharMgr.GetPlayerCharacter(player);
				if (player.dialog.active)
				{
					player.dialog.active = false;
				}
				if (player.dialog.menuMgr.active)
				{
					player.dialog.menuMgr.active = false;
				}
			}
			p.dialog.menuMgr.DoSpecialTrans(0);
			if (hornMode)
			{
				for (int i = 0; i < p.playerInv.inventory.Length; i++)
				{
					if (p.playerInv.inventory[i] != null && p.playerInv.inventory[i].category == 4 && p.playerInv.inventory[i].catalogIdx > -1 && LootCatalog.category[4].loot[p.playerInv.inventory[i].catalogIdx].flags == 74)
					{
						p.playerInv.RemoveConsumable(i, playerCharacter, removeSanctuaryItems: true);
						break;
					}
				}
			}
		}
		for (int j = 0; j < dest.Length; j++)
		{
			if (j == selItem)
			{
				if (dest[j].alpha < 1f)
				{
					dest[j].alpha += Game1.frameTime * 10f;
					if (dest[j].alpha > 1f)
					{
						dest[j].alpha = 1f;
					}
				}
			}
			else if (dest[j].alpha > 0f)
			{
				dest[j].alpha -= Game1.frameTime * 10f;
				if (dest[j].alpha < 0f)
				{
					dest[j].alpha = 0f;
				}
			}
		}
		float num = (float)selItem * 80f;
		float num2 = ((selItem > 0) ? (num - 80f) : num);
		if (scroll > num2)
		{
			scroll -= (scroll - num2) * Game1.frameTime * 10f;
			if (scroll < num2)
			{
				scroll = num2;
			}
		}
		float num3 = 260f;
		float num4 = ((selItem < dest.Length - 1) ? (num - num3 + 80f) : (num - num3));
		if (scroll < num4)
		{
			scroll += (num4 - scroll) * Game1.frameTime * 10f;
			if (scroll > num4)
			{
				scroll = num4;
			}
		}
	}

