namespace ProjectTower.player;

public class PlayerMap
{
	public int width;

	public int height;

	private Player player;

	public bool[,] map;

	public PlayerMap(int w, int h)
	{
		width = w;
		height = h;
		map = new bool[width, height];
	}

	public void Write(BinaryWriter writer)
	{
		writer.Write(width);
		writer.Write(height);
		for (int i = 0; i < width; i++)
		{
			for (int j = 0; j < height; j++)
			{
				writer.Write(map[i, j]);
			}
		}
	}

	public PlayerMap(Player p)
	{
		player = p;
	}

	public void Draw()
	{
		Character playerCharacter = CharMgr.GetPlayerCharacter(player);
		Vector2 vector = new Vector2(110f, 110f);
		Vector2 vector2 = new Vector2((float)MapMgr.worldMap.Width - 40f, MapMgr.worldMap.Height);
		Vector2 vector3 = playerCharacter.loc / new Vector2((float)MapMgr.map.xUnits * 64f, (float)MapMgr.map.yUnits * 64f * 0.5f);
		Vector2 vector4 = vector + (vector2 - vector) * vector3;
		vector4 = new Vector2(115f, 80f) + playerCharacter.loc * new Vector2(0.03875f, 0.03895f);
		SpriteTools.sprite.Draw(MapMgr.worldMap, new Vector2(200f, 200f), new Rectangle((int)vector4.X - 200, (int)vector4.Y - 200, 400, 400), Color.White, 0f, default, 1f, SpriteEffects.None, 1f);
		Textures.tex[ParticleManager.spritesTexIdx].Draw(new Vector2(400f, 400f), 0, new Vector2(1f, 0.1f), 0f, 1f, 1f, 1f, 1f);
		Textures.tex[ParticleManager.spritesTexIdx].Draw(new Vector2(400f, 400f), 0, new Vector2(0.1f, 1f), 0f, 1f, 1f, 1f, 1f);
	}

	public PlayerMap(BinaryReader reader)
	{
		width = reader.ReadInt32();
		height = reader.ReadInt32();
		map = new bool[width, height];
		for (int i = 0; i < width; i++)
		{
			for (int j = 0; j < height; j++)
			{
				map[i, j] = reader.ReadBoolean();
			}
		}
	}
}
using DialogEdit;
using MapEdit.map;
using Microsoft.Xna.Framework;
using ProjectTower.player;
using ProjectTower.texturesheet;
using SheetEdit.TextureSheet;

namespace ProjectTower.map.triggers;

public class Trigger
{
	private Vector2 loc;

	private Vector2 scale;

	public int type;

	private int seq;

	public const int TYPE_TRIG = 0;

	public const int TYPE_DOOR = 1;

	public const int TYPE_LADDER_KICK = 2;

	public const int TYPE_SECRET_DOOR = 3;

	public const int TYPE_SECRET_SLASH = 4;

	public const int TYPE_AREA = 5;

	public const int TYPE_CANDLE_TREE = 6;

	private Vector2 srcScale;

	public bool firable;

	public string key;

	public Trigger(Seg seg)
	{
		Init(seg);
	}

	internal void Init(Seg seg)
	{
		loc = seg.loc;
		scale = seg.scaling;
		key = null;
		XSprite originalCell = Textures.tex[seg.textureIdx].GetOriginalCell(seg.idx);
		switch (originalCell.flags)
		{
		case 13:
			type = 0;
			seq = seg.intFlag;
			break;
		case 14:
			type = 1;
			seq = seg.intFlag;
			break;
		case 86:
			type = 6;
			break;
		case 29:
			type = 3;
			seq = seg.intFlag;
			break;
		case 30:
			type = 4;
			seq = seg.intFlag;
			break;
		case 15:
			type = 2;
			seq = seg.intFlag;
			break;
		}
		srcScale = new Vector2(originalCell.srcRect.Width, originalCell.srcRect.Height);
		srcScale /= 2f;
		if (seg.strFlag != null)
		{
			string[] array = seg.strFlag.Split('\n');
			for (int i = 0; i < array.Length; i++)
			{
				if (array[i].EndsWith("\r"))
				{
					array[i] = array[i].Substring(0, array[i].Length - 1);
				}
			}
			for (int j = 0; j < array.Length; j++)
			{
				string[] array2 = array[j].Split(' ');
				if (array2[0] == "key")
				{
					key = array2[1];
				}
			}
		}
		firable = true;
	}

	public bool GetIntersect(Vector2 v)
	{
		_ = loc;
		_ = srcScale;
		_ = scale;
		if (v.X > loc.X - srcScale.X * scale.X && v.X < loc.X + srcScale.X * scale.X && v.Y > loc.Y - srcScale.Y * scale.Y)
		{
			return v.Y < loc.Y + srcScale.Y * scale.Y;
		}
		return false;
	}

	internal void SetFromPlayer(Player p)
	{
		for (int i = 0; i < p.flags.Count; i++)
		{
			if (type != 6 && MapMgr.map.sequenceMgr.sequences[seq].name == p.flags[i])
			{
				firable = false;
			}
		}
	}

	internal void Fire(Player p)
	{
		if (key != null)
		{
			if (!p.playerInv.HasKey(key))
			{
				p.prompts.MakeMessage(LocStrings.GetLocStr(1062));
				return;
			}
			p.prompts.MakeMessage(LocStrings.GetLocStr(1063).Replace("[key]", p.playerInv.GetKeyName(key)));
		}
		firable = false;
		MapMgr.map.sequenceMgr.sequences[seq].Activate();
		PlayerMgr.SetMainPlayerFlag(MapMgr.map.sequenceMgr.sequences[seq].name);
	}
}

