	public void UpdateRunes(InvLoot invLoot)
	{
		int num = 0;
		for (int i = 0; i < p.runes.Length; i++)
		{
			p.runes[i] = false;
		}
		for (int j = 0; j < inventory.Length; j++)
		{
			InvLoot invLoot2 = inventory[j];
			if (invLoot2 != null && invLoot2.category == 3)
			{
				LootDef lootDef = LootCatalog.category[invLoot2.category].loot[invLoot2.catalogIdx];
				if (lootDef.type == 2 && lootDef.flags < p.runes.Length)
				{
					p.runes[lootDef.flags] = true;
					num++;
				}
			}
		}
		if (p.ID == GameStateManager.coopPlayerIdx)
		{
			Player mainPlayer = PlayerMgr.GetMainPlayer();
			for (int k = 0; k < p.runes.Length; k++)
			{
				if (mainPlayer.runes[k])
				{
					p.runes[k] = true;
				}
			}
		}
		else if (p.ID == GameStateManager.mainPlayerIdx && GameStateManager.coopPlayerIdx > -1)
		{
			Player coopPlayer = PlayerMgr.GetCoopPlayer();
			for (int l = 0; l < p.runes.Length; l++)
			{
				if (p.runes[l])
				{
					coopPlayer.runes[l] = true;
				}
			}
		}
